import com.cowave.search.controller.dto.CreateDictionaryRequest
import com.cowave.search.controller.dto.CursorPagedResponse
import com.cowave.search.controller.dto.SearchColumn
import com.cowave.search.controller.dto.SortType
import com.cowave.search.controller.dto.TypeCountResponse
import com.cowave.search.controller.dto.TypeLastModifiedResponse
import com.cowave.search.controller.dto.UpdateDictionaryRequest
import com.cowave.search.domain.dictionary.Dictionary
import com.cowave.search.domain.dictionary.Type
import com.cowave.search.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/api/v1/dictionary")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    /**
     * 사전 조회/검색 통합 API
     * - word가 없으면 전체 조회
     * - word가 있으면 검색 (searchColumn에 따라 대상 필드 결정)
     */
    @GetMapping("/{type}")
    fun getDictionary(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
        @RequestParam(defaultValue = "UPDATED") sort: SortType,
        @RequestParam(defaultValue = "ALL") searchColumn: SearchColumn,
        @RequestParam(required = false) word: String?,
        @RequestParam(defaultValue = "false") isMatch: Boolean,
    ): CursorPagedResponse<Dictionary> =
        dictionaryService.search(
            type = type,
            size = size,
            searchColumn = searchColumn,
            word = word,
            isMatch = isMatch,
            cursor = cursor,
            sortType = sort,
        )

    @GetMapping("/{type}/count")
    fun countByType(
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(type))

    @GetMapping("/{type}/last-modified")
    fun getLastModifiedByType(
        @PathVariable type: Type,
    ): TypeLastModifiedResponse = dictionaryService.getLastModifiedByType(type)

    @GetMapping("/last-modified")
    fun getAllTypesLastModified(): AllTypesLastModifiedResponse = dictionaryService.getAllTypesLastModified()

    @GetMapping("/count")
    fun getAllTypesCounts(): AllTypesCountResponse = dictionaryService.getAllTypesCounts()

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

package com.cowave.search.infrastructure

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOptions
import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch._types.query_dsl.BoolQuery
import co.elastic.clients.elasticsearch._types.query_dsl.Query
import com.cowave.search.controller.dto.SearchColumn
import com.cowave.search.controller.dto.SortType
import com.cowave.search.domain.dictionary.Dictionary
import com.cowave.search.domain.dictionary.Type
import com.cowave.search.domain.document.SearchAfterResult
import com.cowave.search.service.DictionaryRepository
import org.springframework.stereotype.Repository
import java.time.Instant

@Repository
class DictionaryRepositoryImpl(
    val esClient: ElasticsearchClient,
) : DictionaryRepository {
    override fun insert(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        esClient.index {
            it.index(DICTIONARY_INDEX)
            it.document(
                Dictionary.of(
                    keyword = keyword,
                    type = type,
                    value = value,
                    createdTime = Instant.now(),
                    updatedTime = Instant.now(),
                ),
            )
        }
    }

    override fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        esClient.update(
            {
                it
                    .index(DICTIONARY_INDEX)
                    .id(id)
                    .doc(
                        mapOf(
                            "keyword" to keyword,
                            "value" to value,
                            "updatedTime" to Instant.now(),
                        ),
                    )
            },
            Dictionary::class.java,
        )
    }

    override fun delete(id: String) {
        esClient.delete {
            it.index(DICTIONARY_INDEX).id(id)
        }
    }

    override fun search(
        type: Type,
        size: Int,
        searchColumn: SearchColumn,
        value: String?,
        isMatch: Boolean,
        searchAfter: List<String>?,
        sortType: SortType,
    ): SearchAfterResult<Dictionary> {
        val sortQuery =
            when (sortType) {
                SortType.UPDATED -> searchAfterSortQuery()
                SortType.KEYWORD -> keywordSearchAfterSortQuery(type)
            }

        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .trackTotalHits { it.enabled(true) }
                        .query { q ->
                            q.bool { b ->
                                // type 필터 (항상 적용)
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                                // 검색어가 있을 때만 검색 쿼리 추가
                                if (value != null) {
                                    addSearchQuery(b, searchColumn, value, isMatch)
                                }
                                b
                            }
                        }.size(size)
                        .sort(sortQuery)
                        .apply {
                            searchAfter?.let { sa ->
                                searchAfter(sa.map { FieldValue.of(it) })
                            }
                        }
                },
                Dictionary::class.java,
            )

        val hits = response.hits().hits()
        val items =
            hits.mapNotNull { hit ->
                hit.id()?.let { id ->
                    hit.source()?.let { Dictionary(id, it.keyword, it.type, it.value, it.createdTime, it.updatedTime) }
                }
            }
        val total = response.hits().total()?.value() ?: 0L
        val nextSearchAfter =
            hits.lastOrNull()?.sort()?.map { fieldValue ->
                fieldValue._get().toString()
            }
        val hasNext = hits.size == size && nextSearchAfter != null

        return SearchAfterResult(items, total, nextSearchAfter, hasNext)
    }

    /**
     * 검색 쿼리를 BoolQuery에 추가
     */
    private fun addSearchQuery(
        boolQuery: BoolQuery.Builder,
        searchColumn: SearchColumn,
        value: String,
        isMatch: Boolean,
    ) {
        val fields =
            when (searchColumn) {
                SearchColumn.ALL -> listOf("keyword", "value")
                SearchColumn.KEYWORD -> listOf("keyword")
                SearchColumn.VALUE -> listOf("value")
            }

        val shouldQueries =
            fields.map { field ->
                if (isMatch) {
                    Query.of { q ->
                        q.match { m ->
                            m.field(field)
                            m.query { qv -> qv.stringValue(value) }
                        }
                    }
                } else {
                    Query.of { q ->
                        q.wildcard { w ->
                            w.field(field)
                            w.value("*$value*")
                        }
                    }
                }
            }

        boolQuery.should(shouldQueries)
        boolQuery.minimumShouldMatch("1")
    }

    override fun findAllByType(type: Type): List<Dictionary> {
        val allResults = mutableListOf<Dictionary>()
        var searchAfter: List<FieldValue>? = null
        val batchSize = 10000

        do {
            val response =
                esClient.search(
                    { s ->
                        s
                            .index(DICTIONARY_INDEX)
                            .query { q ->
                                q.term { t ->
                                    t
                                        .field("type")
                                        .value { v -> v.stringValue(type.toString()) }
                                }
                            }.size(batchSize)
                            .sort { so ->
                                so.field { f ->
                                    f.field("createdTime").order(SortOrder.Asc)
                                }
                            }.apply {
                                searchAfter?.let { sa -> searchAfter(sa) }
                            }
                    },
                    Dictionary::class.java,
                )

            val hits = response.hits().hits()
            hits.mapNotNull { it.source() }.let { allResults.addAll(it) }

            searchAfter = hits.lastOrNull()?.sort()
        } while (searchAfter != null && response.hits().hits().size == batchSize)

        return allResults
    }

    override fun findLastModifiedByType(type: Type): Pair<Instant?, Long> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results, not documents
                        .query { q ->
                            q.term { t ->
                                t.field("type").value(type.name)
                            }
                        }.aggregations("max_updated_time") { agg ->
                            agg.max { m -> m.field("updatedTime") }
                        }
                },
                Dictionary::class.java,
            )

        val total = response.hits().total()?.value() ?: 0L
        val maxAgg = response.aggregations()["max_updated_time"]?.max()
        // ES returns NaN for empty aggregation results
        val lastModified =
            maxAgg?.value()?.takeIf { !it.isNaN() }?.let {
                Instant.ofEpochMilli(it.toLong())
            }

        return Pair(lastModified, total)
    }

    override fun findLastModifiedForAllTypes(): Map<Type, Pair<Instant?, Long>> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results
                        .aggregations("by_type") { agg ->
                            agg
                                .terms { t ->
                                    t.field("type").size(Type.entries.size)
                                }.aggregations("max_updated_time") { subAgg ->
                                    subAgg.max { m -> m.field("updatedTime") }
                                }
                        }
                },
                Dictionary::class.java,
            )

        val byTypeAgg = response.aggregations()["by_type"]?.sterms()
        val resultMap = mutableMapOf<Type, Pair<Instant?, Long>>()

        // Initialize all types with null/0
        Type.entries.forEach { type ->
            resultMap[type] = Pair(null, 0L)
        }

        // Update with actual values from aggregation
        byTypeAgg?.buckets()?.array()?.forEach { bucket ->
            val typeName = bucket.key().stringValue()
            val type = Type.entries.find { it.name == typeName }
            if (type != null) {
                val count = bucket.docCount()
                val maxAgg = bucket.aggregations()["max_updated_time"]?.max()
                val lastModified =
                    maxAgg?.value()?.takeIf { !it.isNaN() }?.let {
                        Instant.ofEpochMilli(it.toLong())
                    }
                resultMap[type] = Pair(lastModified, count)
            }
        }

        return resultMap
    }

    override fun countByType(type: Type): Long =
        esClient
            .count {
                it
                    .index(DICTIONARY_INDEX)
                    .query { q ->
                        q.term { t ->
                            t.field("type").value(type.name)
                        }
                    }
            }.count()

    override fun countAllTypes(): Map<Type, Long> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .size(0) // We only need aggregation results
                        .aggregations("by_type") { agg ->
                            agg.terms { t ->
                                t.field("type").size(Type.entries.size)
                            }
                        }
                },
                Dictionary::class.java,
            )

        val byTypeAgg = response.aggregations()["by_type"]?.sterms()
        val resultMap = mutableMapOf<Type, Long>()

        // Initialize all types with 0
        Type.entries.forEach { type ->
            resultMap[type] = 0L
        }

        // Update with actual values from aggregation
        byTypeAgg?.buckets()?.array()?.forEach { bucket ->
            val typeName = bucket.key().stringValue()
            val type = Type.entries.find { it.name == typeName }
            if (type != null) {
                resultMap[type] = bucket.docCount()
            }
        }

        return resultMap
    }

    private fun baseSortQuery() =
        SortOptions.of {
            it.field { f ->
                f.field("updatedTime")
                f.order(SortOrder.Desc)
            }
            it.field { f2 ->
                f2.field("createdTime")
                f2.order(SortOrder.Desc)
            }
        }

    private fun searchAfterSortQuery(): List<SortOptions> =
        listOf(
            SortOptions.of { it.field { f -> f.field("updatedTime").order(SortOrder.Desc) } },
            SortOptions.of { it.field { f -> f.field("createdTime").order(SortOrder.Desc) } },
            // Use _shard_doc instead of _id (ES 8.x disallows _id fielddata by default)
            SortOptions.of { it.field { f -> f.field("_shard_doc").order(SortOrder.Asc) } },
        )

    private fun keywordSortQuery(type: Type) =
        SortOptions.of {
            it.field { f ->
                f.field(getSortFieldForType(type))
                f.order(SortOrder.Asc)
            }
        }

    private fun keywordSearchAfterSortQuery(type: Type): List<SortOptions> =
        listOf(
            SortOptions.of { it.field { f -> f.field(getSortFieldForType(type)).order(SortOrder.Asc) } },
            SortOptions.of { it.field { f -> f.field("_shard_doc").order(SortOrder.Asc) } },
        )

    private fun getSortFieldForType(type: Type): String =
        when (type) {
            Type.SYNONYM, Type.COMPOUND, Type.UNIT_SYNONYM -> "value.raw"
            else -> "keyword"
        }

    companion object {
        const val DICTIONARY_INDEX = ".dsearch_dict"
    }
}

package com.cowave.search.utils

import com.cowave.search.config.DictionaryConfig
import com.cowave.search.domain.dictionary.Type
import org.springframework.stereotype.Component
import java.io.File

/**
 * 사전 바이너리 컴파일러
 * ES 인덱스에서 읽은 사전 데이터를 바이너리 파일로 컴파일
 *
 * 기존 Java analysis-product의 사전 바이너리 형식과 100% 호환
 */
@Component
class DictionaryBinaryCompile(
    private val dictionaryConfig: DictionaryConfig,
) {
    /**
     * 설정된 출력 경로 반환
     */
    fun getOutputPath(): String = dictionaryConfig.outputPath

    /**
     * Type에 따른 출력 파일 경로 반환 (설정된 경로 사용)
     */
    fun getOutputFile(type: Type): File = File(dictionaryConfig.outputPath, getOutputFileName(type))

    /**
     * ES에서 조회한 Dictionary 목록을 설정된 경로에 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 생성된 파일
     */
    fun compileToConfiguredPath(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        ignoreCase: Boolean = true,
    ): File {
        val outputFile = getOutputFile(type)
        compileFromDictionaries(dictionaries, type, outputFile, ignoreCase)
        return outputFile
    }

    /**
     * 설정된 경로에서 사전 파일 로드
     * @param type 사전 타입
     * @param ignoreCase 대소문자 무시 여부
     * @return 로드된 사전 데이터
     */
    fun loadFromConfiguredPath(
        type: Type,
        ignoreCase: Boolean = true,
    ): Any = load(type, getOutputFile(type), ignoreCase)

    /**
     * 기존 Type enum과 매핑하여 사전 컴파일
     * SET 타입: STOP, UNIT, USER, ENGLISH
     * SYNONYM 타입: SYNONYM, UNIT_SYNONYM
     * SPACE 타입: SPACE
     * COMPOUND 타입: COMPOUND
     */
    fun compile(
        type: Type,
        data: Any,
        outputFile: File,
    ) {
        outputFile.parentFile?.mkdirs()

        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.writeTo(data as SetDictionaryData, outputFile)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.writeTo(data as SynonymDictionaryData, outputFile)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.writeTo(data as SpaceDictionaryData, outputFile)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.writeTo(data as CompoundDictionaryData, outputFile)
            }
        }
    }

    /**
     * 바이너리 사전 파일을 읽어서 데이터 객체로 반환
     */
    fun load(
        type: Type,
        inputFile: File,
        ignoreCase: Boolean = true,
    ): Any =
        when (type) {
            Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                SetDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SYNONYM, Type.UNIT_SYNONYM -> {
                SynonymDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.SPACE -> {
                SpaceDictionarySerializer.readFrom(inputFile, ignoreCase)
            }

            Type.COMPOUND -> {
                CompoundDictionarySerializer.readFrom(inputFile, ignoreCase)
            }
        }

    /**
     * ES에서 조회한 Dictionary 목록을 타입별로 컴파일
     * @param dictionaries ES에서 조회한 사전 데이터 (keyword, value 쌍)
     * @param type 사전 타입
     * @param outputFile 출력 파일
     * @param ignoreCase 대소문자 무시 여부
     */
    fun compileFromDictionaries(
        dictionaries: List<Pair<String?, String?>>,
        type: Type,
        outputFile: File,
        ignoreCase: Boolean = true,
    ) {
        val data =
            when (type) {
                Type.STOP, Type.UNIT, Type.USER, Type.ENGLISH -> {
                    // SET 타입: keyword만 사용
                    val words =
                        dictionaries
                            .mapNotNull { it.first?.trim() }
                            .filter { it.isNotEmpty() }
                            .toSet()
                    SetDictionaryData(words, ignoreCase)
                }

                Type.SYNONYM, Type.UNIT_SYNONYM -> {
                    // SYNONYM 타입: keyword -> value 매핑
                    createSynonymFromPairs(dictionaries, ignoreCase)
                }

                Type.SPACE -> {
                    // SPACE 타입: keyword -> value (공백 분리)
                    createSpaceFromPairs(dictionaries, ignoreCase)
                }

                Type.COMPOUND -> {
                    // COMPOUND 타입: keyword -> value (복합어 분해)
                    createCompoundFromPairs(dictionaries, ignoreCase)
                }
            }
        compile(type, data, outputFile)
    }

    /**
     * SYNONYM 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createSynonymFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SynonymDictionaryData {
        val synonymMap = mutableMapOf<String, MutableList<String>>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (value.isNullOrBlank()) continue

            val synonyms = value.split(",").map { it.trim() }.filter { it.isNotEmpty() }

            if (!keyword.isNullOrBlank()) {
                // 단방향: keyword -> synonyms
                val key = keyword.trim()
                synonymMap.getOrPut(key) { mutableListOf() }.addAll(synonyms)
                wordSet.add(key)
                wordSet.addAll(synonyms)
            } else {
                // 양방향: 모든 단어가 서로 동의어
                for (word in synonyms) {
                    val others = synonyms.filter { it != word }
                    synonymMap.getOrPut(word) { mutableListOf() }.addAll(others)
                }
                wordSet.addAll(synonyms)
            }
        }

        return SynonymDictionaryData(synonymMap, wordSet, ignoreCase)
    }

    /**
     * SPACE 타입 사전 생성 (keyword, value 쌍으로부터)
     *
     * Java 원본(SpaceDictionary.java:60-73)과 100% 동일한 로직:
     * 1. values[0]에서 공백을 제거하여 key 생성
     * 2. values[0]을 공백으로 split하여 value 배열 생성 (빈 문자열 포함!)
     * 3. wordSet에는 key와 비-ASCII 단어만 추가
     *
     * IMPORTANT: Java는 split("\\s")를 사용하여 연속 공백 시 빈 문자열이 생성됨
     * 예: "클린  스트라이프" → ["클린", "", "스트라이프"]
     * 빈 문자열은 RuleOne.java:45에서 setDisableEntry() 트리거하여 분석 동작에 영향
     * 바이너리 호환성을 위해 빈 문자열을 그대로 유지해야 함
     */
    private fun createSpaceFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): SpaceDictionaryData {
        val spaceMap = mutableMapOf<String, List<String>>()
        val wordSet = mutableSetOf<String>()
        // Java: Pattern.compile("^[\\x00-\\x7F]*$") - ASCII 패턴
        val asciiPattern = Regex("^[\\x00-\\x7F]*$")

        for ((keyword, value) in pairs) {
            // Java: values[0]만 사용 - ES 데이터에서는 keyword 또는 value 중 하나 사용
            val sourceText = keyword?.takeIf { it.isNotBlank() } ?: value
            if (sourceText.isNullOrBlank()) continue

            // SPACE 타입 분리어 사전 때문에 아래와 같이 필요
            // - "\\s+"를 사용하면 연속 공백이 하나로 병합되어 리스트 길이가 달라짐
            // - 예: "가 나  다".split("\\s") → ["가", "나", "", "다"] (4개)
            //       "가 나  다".split("\\s+") → ["가", "나", "다"] (3개)
            // - 바이너리 포맷이 리스트 길이를 저장하므로 Java와 동일해야 함
            val key = sourceText.replace(Regex("\\s"), "")
            if (key.isEmpty()) continue

            val splitWords =
                sourceText
                    .split(Regex("\\s"))
                    .map { it.trim() }
            // 빈 문자열 유지: .filter { it.isNotEmpty() } 제거

            spaceMap[key] = splitWords
            wordSet.add(key) // 공백 제거된 키 추가

            // Java: ASCII 패턴 매치 안되는 것만 추가 (비-ASCII 단어만)
            // 빈 문자열은 ASCII로 매치되므로 wordSet에 추가되지 않음
            for (word in splitWords) {
                if (word.isNotEmpty() && !asciiPattern.matches(word)) {
                    wordSet.add(word)
                }
            }
        }

        return SpaceDictionaryData(spaceMap, wordSet, ignoreCase)
    }

    /**
     * COMPOUND 타입 사전 생성 (keyword, value 쌍으로부터)
     */
    private fun createCompoundFromPairs(
        pairs: List<Pair<String?, String?>>,
        ignoreCase: Boolean,
    ): CompoundDictionaryData {
        val compoundMap = mutableMapOf<String, List<String>>()
        val mainWordSet = mutableSetOf<String>()
        val wordSet = mutableSetOf<String>()

        for ((keyword, value) in pairs) {
            if (keyword.isNullOrBlank() || value.isNullOrBlank()) continue

            val key = keyword.trim()
            val parts =
                value
                    .split(",")
                    .map { it.trim() }
                    .filter { it.isNotEmpty() }

            compoundMap[key] = parts
            mainWordSet.add(key)
            wordSet.addAll(parts)
        }

        return CompoundDictionaryData(compoundMap, mainWordSet, wordSet, ignoreCase)
    }

    /**
     * Type에 따른 출력 파일명 생성
     */
    fun getOutputFileName(type: Type): String =
        when (type) {
            Type.STOP -> "stop.dict"
            Type.UNIT -> "unit.dict"
            Type.USER -> "user.dict"
            Type.ENGLISH -> "english.dict"
            Type.SYNONYM -> "synonym.dict"
            Type.UNIT_SYNONYM -> "unit_synonym.dict"
            Type.SPACE -> "space.dict"
            Type.COMPOUND -> "compound.dict"
        }
}

package com.cowave.search.utils

import java.io.BufferedInputStream
import java.io.BufferedOutputStream
import java.io.Closeable
import java.io.EOFException
import java.io.IOException
import java.io.InputStream
import java.io.OutputStream

/**
 * 바이너리 데이터 출력 클래스
 * Lucene 스타일의 가변길이 인코딩 지원
 * 기존 Java analysis-product의 DataOutput과 100% 호환
 */
class BinaryDataOutput(
    private val out: OutputStream,
) : Closeable {
    private val buffered: BufferedOutputStream =
        out as? BufferedOutputStream ?: BufferedOutputStream(out)

    fun writeByte(b: Int) {
        buffered.write(b)
    }

    fun writeBytes(
        b: ByteArray,
        offset: Int = 0,
        length: Int = b.size,
    ) {
        buffered.write(b, offset, length)
    }

    /**
     * 4바이트 정수 (Big-Endian)
     */
    fun writeInt(i: Int) {
        writeByte((i shr 24) and 0xFF)
        writeByte((i shr 16) and 0xFF)
        writeByte((i shr 8) and 0xFF)
        writeByte(i and 0xFF)
    }

    /**
     * 2바이트 정수 (Big-Endian)
     */
    fun writeShort(i: Int) {
        writeByte((i shr 8) and 0xFF)
        writeByte(i and 0xFF)
    }

    /**
     * 가변길이 정수 (1-5 bytes)
     * 작은 값은 적은 바이트 사용
     */
    fun writeVInt(value: Int) {
        var i = value
        while ((i and 0x7F.inv()) != 0) {
            writeByte((i and 0x7F) or 0x80)
            i = i ushr 7
        }
        writeByte(i)
    }

    /**
     * 8바이트 Long
     */
    fun writeLong(i: Long) {
        writeInt((i shr 32).toInt())
        writeInt(i.toInt())
    }

    /**
     * 가변길이 Long (1-9 bytes)
     */
    fun writeVLong(value: Long) {
        var i = value
        require(i >= 0L) { "Negative values not supported" }
        while ((i and 0x7FL.inv()) != 0L) {
            writeByte(((i and 0x7FL) or 0x80L).toInt())
            i = i ushr 7
        }
        writeByte(i.toInt())
    }

    fun writeFloat(v: Float) {
        writeInt(java.lang.Float.floatToIntBits(v))
    }

    fun writeDouble(v: Double) {
        writeLong(java.lang.Double.doubleToLongBits(v))
    }

    fun writeBoolean(b: Boolean) {
        writeByte(if (b) 1 else 0)
    }

    /**
     * 유니코드 문자열 (2바이트/문자)
     * 형식: VInt(byteLength) + chars (each 2 bytes)
     */
    fun writeUString(
        chars: CharArray,
        start: Int = 0,
        length: Int = chars.size,
    ) {
        writeVInt(length * 2)
        for (i in 0 until length) {
            writeShort(chars[start + i].code)
        }
    }

    fun writeUString(str: String) {
        writeUString(str.toCharArray(), 0, str.length)
    }

    /**
     * 일반 문자열 (내부적으로 writeUString 사용)
     */
    fun writeString(str: String?) {
        val s = str ?: ""
        writeUString(s.toCharArray(), 0, s.length)
    }

    /**
     * ASCII 문자열 (1바이트/문자)
     */
    fun writeAString(
        chars: CharArray,
        start: Int = 0,
        length: Int = chars.size,
    ) {
        writeVInt(length)
        for (i in 0 until length) {
            writeByte(chars[start + i].code)
        }
    }

    fun flush() {
        buffered.flush()
    }

    override fun close() {
        flush()
        buffered.close()
    }
}

/**
 * 바이너리 데이터 입력 클래스
 * 기존 Java analysis-product의 DataInput과 100% 호환
 */
class BinaryDataInput(
    private val input: InputStream,
) : Closeable {
    private val buffered: BufferedInputStream =
        input as? BufferedInputStream ?: BufferedInputStream(input)

    fun readByte(): Int {
        val b = buffered.read()
        if (b == -1) throw EOFException("Unexpected end of stream")
        return b
    }

    fun readBytes(
        b: ByteArray,
        offset: Int = 0,
        len: Int = b.size,
    ) {
        var remaining = len
        var off = offset
        while (remaining > 0) {
            val read = buffered.read(b, off, remaining)
            if (read == -1) throw EOFException("Unexpected end of stream")
            remaining -= read
            off += read
        }
    }

    fun readInt(): Int =
        ((readByte() and 0xFF) shl 24) or
            ((readByte() and 0xFF) shl 16) or
            ((readByte() and 0xFF) shl 8) or
            (readByte() and 0xFF)

    fun readShort(): Int = ((readByte() and 0xFF) shl 8) or (readByte() and 0xFF)

    fun readVInt(): Int {
        var b = readByte()
        if (b >= 0) return b

        var i = b and 0x7F
        b = readByte()
        i = i or ((b and 0x7F) shl 7)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F) shl 14)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F) shl 21)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x0F) shl 28)
        if ((b and 0xF0) == 0) return i

        throw IOException("Invalid vInt detected (too many bits)")
    }

    fun readLong(): Long = (readInt().toLong() shl 32) or (readInt().toLong() and 0xFFFFFFFFL)

    fun readVLong(): Long {
        var b = readByte()
        if (b >= 0) return b.toLong()

        var i = (b and 0x7F).toLong()
        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 7)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 14)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 21)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 28)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 35)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 42)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 49)
        if (b >= 0) return i

        b = readByte()
        i = i or ((b and 0x7F).toLong() shl 56)
        if (b >= 0) return i

        throw IOException("Invalid vLong detected")
    }

    fun readFloat(): Float = java.lang.Float.intBitsToFloat(readInt())

    fun readDouble(): Double = java.lang.Double.longBitsToDouble(readLong())

    fun readBoolean(): Boolean = readByte() != 0

    fun readUString(): CharArray {
        val byteSize = readVInt()
        val chars = CharArray(byteSize / 2)
        for (i in chars.indices) {
            chars[i] = readShort().toChar()
        }
        return chars
    }

    fun readString(): String = String(readUString())

    fun readAString(): CharArray {
        val len = readVInt()
        val chars = CharArray(len)
        for (i in 0 until len) {
            chars[i] = readByte().toChar()
        }
        return chars
    }

    override fun close() {
        buffered.close()
    }
}

package com.cowave.search.utils

import java.io.File
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.io.InputStream
import java.io.OutputStream

/**
 * SET 타입 사전 직렬화/역직렬화
 *
 * 바이너리 형식:
 * - Int: 엔트리 개수
 * - String[]: 각 단어 (UString 형식)
 */
object SetDictionarySerializer {
    fun writeTo(
        data: SetDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            // write size
            output.writeInt(data.words.size)

            // write each word
            for (word in data.words) {
                output.writeString(word)
            }

            output.flush()
        }
    }

    fun writeTo(
        data: SetDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): SetDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val size = input.readInt()
            val words = mutableSetOf<String>()

            repeat(size) {
                val word = input.readString()
                words.add(if (ignoreCase) word.uppercase() else word)
            }

            return SetDictionaryData(words, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): SetDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * MAP 타입 사전 직렬화/역직렬화
 *
 * 바이너리 형식:
 * - VInt: 맵 크기
 * - 각 엔트리:
 *   - UString: 키
 *   - VInt: 값 배열 크기
 *   - UString[]: 값들
 */
object MapDictionarySerializer {
    fun writeTo(
        data: MapDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            writeMapData(output, data.entries)
            output.flush()
        }
    }

    internal fun writeMapData(
        output: BinaryDataOutput,
        entries: Map<String, List<String>>,
    ) {
        // write map size
        output.writeVInt(entries.size)

        // write each entry
        for ((key, values) in entries) {
            // write key
            output.writeUString(key)

            // write values
            output.writeVInt(values.size)
            for (value in values) {
                output.writeUString(value)
            }
        }
    }

    fun writeTo(
        data: MapDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): MapDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val entries = readMapData(input, ignoreCase)
            return MapDictionaryData(entries, ignoreCase)
        }
    }

    internal fun readMapData(
        input: BinaryDataInput,
        ignoreCase: Boolean,
    ): Map<String, List<String>> {
        val size = input.readVInt()
        val entries = mutableMapOf<String, List<String>>()

        repeat(size) {
            val key =
                input.readString().let {
                    if (ignoreCase) it.uppercase() else it
                }

            val valueLength = input.readVInt()
            val values = mutableListOf<String>()

            repeat(valueLength) {
                val value =
                    input.readString().let {
                        if (ignoreCase) it.uppercase() else it
                    }
                values.add(value)
            }

            entries[key] = values
        }

        return entries
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): MapDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * INVERT_MAP 타입 사전 직렬화/역직렬화
 *
 * Java InvertMapDictionary와 동일한 바이너리 포맷 (MapDictionary 형식)
 * 역방향 매핑은 데이터 생성 시 처리되므로, 직렬화 포맷은 MapDictionary와 동일
 *
 * 바이너리 형식:
 * - VInt: 맵 크기
 * - 각 엔트리:
 *   - UString: 키 (원본의 value)
 *   - VInt: 값 배열 크기
 *   - UString[]: 값들 (원본의 key)
 */
object InvertMapDictionarySerializer {
    fun writeTo(
        data: InvertMapDictionaryData,
        outputStream: OutputStream,
    ) {
        BinaryDataOutput(outputStream).use { output ->
            MapDictionarySerializer.writeMapData(output, data.entries)
            output.flush()
        }
    }

    fun writeTo(
        data: InvertMapDictionaryData,
        file: File,
    ) {
        file.parentFile?.mkdirs()
        FileOutputStream(file).use { fos ->
            writeTo(data, fos)
        }
    }

    fun readFrom(
        inputStream: InputStream,
        ignoreCase: Boolean = true,
    ): InvertMapDictionaryData {
        BinaryDataInput(inputStream).use { input ->
            val entries = MapDictionarySerializer.readMapData(input, ignoreCase)
            return InvertMapDictionaryData(entries, ignoreCase)
        }
    }

    fun readFrom(
        file: File,
        ignoreCase: Boolean = true,
    ): InvertMapDictionaryData =
        FileInputStream(file).use { fis ->
            readFrom(fis, ignoreCase)
        }
}

/**
 * SYNONYM 타입 사전 직렬화/역직렬화
 * MapDictionary 형식 + wordSet
 *
